{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In humans, DX-9065a had a very low absolute oral bioavailability of 2–3%, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Avanafil at 200 mg in humans showed a bioavailability of 8–10%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Atenolol after a single 100 mg oral dose had a mean absolute bioavailability of 60 ± 8%, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules indicate low absolute oral bioavailability (2–3%, 8–10%, ≤3%, 19%), supporting F < 20%; the positive atenolol and dose-dependent L-arginine records are outweighed by the higher-score negative evidence. Fed-state-specific data are absent, so confidence is moderate.",
  "evidence_gaps": [
    "No records explicitly under fed-state conditions; most evidence is fasted or unspecified, so a food effect on F is unaddressed.",
    "Molecule 5 contains a provenance conflict (a citrulline record grouped with L-arginine) and dose-dependent bioavailability, adding uncertainty to the positive evidence.",
    "Molecule 9 includes an altered-condition record in cirrhotic patients measuring metabolite availability, which is less direct."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

